  const contextMessage=new Date().getHours()<12?`☀️ Bom dia, ${student.name.split(' ')[0]}! Comece sua hidratação e registre o café da manhã.`:new Date().getHours()<17?`🌤️ Como está sua rotina hoje? Sua próxima refeição pode ser planejada com o que você tem disponível.`:`🌙 Como foi sua alimentação hoje? Registre o que comeu para acompanhar sua evolução.`;
  const addWater=async(amount_ml:number)=>{try{await studentPost('/student-api/nutrigym/hydration',{amount_ml});await load();notify(`+${amount_ml} ml registrados`)}catch(e:any){notify(e.message)}};
  const addShopping=async(e:React.FormEvent)=>{e.preventDefault();if(!shoppingText.trim())return;try{const item=await studentPost('/student-api/nutrigym/shopping',{item:shoppingText.trim(),category:'Outros'});setShopping(x=>[...x,item]);setShoppingText('');notify('Item adicionado')}catch(e:any){notify(e.message)}};const toggleShopping=async(item:any)=>{try{const updated=await studentPut('/student-api/nutrigym/shopping/'+item.id,{item:item.item,quantity:item.quantity,purchased:!item.purchased});setShopping(x=>x.map(i=>i.id===item.id?updated:i))}catch(e:any){notify(e.message)}};const saveProfile=async()=>{setProfileOpen(false);await load();notify('Perfil atualizado')};
